package com.mytele.mtp2026.launcher;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import java.util.*;
public final class MainActivity extends Activity{private WebView w;private final Set<String>a=new HashSet<>();@Override public void onCreate(Bundle b){super.onCreate(b);Uri s=Uri.parse(BuildConfig.WEB_APP_URL);if(s.getHost()!=null)a.add(s.getHost());a.add("api-vexaaccount.onrender.com");w=new WebView(this);setContentView(w);w.setWebChromeClient(new WebChromeClient());w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();String h=u.getHost();if("https".equalsIgnoreCase(u.getScheme())&&h!=null&&a.contains(h))return false;startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}});WebSettings x=w.getSettings();x.setJavaScriptEnabled(true);x.setDomStorageEnabled(true);x.setDatabaseEnabled(true);x.setAllowFileAccess(false);x.setAllowContentAccess(false);x.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptCookie(true);w.loadUrl(BuildConfig.WEB_APP_URL);}@Override public void onBackPressed(){if(w!=null&&w.canGoBack())w.goBack();else super.onBackPressed();}@Override protected void onDestroy(){if(w!=null){w.loadUrl("about:blank");w.stopLoading();w.destroy();}super.onDestroy();}}
